const billing={audience:'learner',orders:[]};
const paidPlans=[
{id:'teacher-services',role:'teacher',name:'Teacher Services',purpose:'PAID — tuition, coaching & expert services',price:499,features:['Up to 3 active service listings','Match with learner requirements','Chat, quote and track engagement status','Direct learner contact after accepted quote, consent and professional agreement']},
{id:'institution',role:'institution',name:'Institution Membership',purpose:'Hiring, admissions & partnerships',price:1999,features:['Post staffing requirements','Discover and shortlist teacher profiles','Manage hiring conversations and direct contact','Promote admissions and explore training partners']},
{id:'training',role:'training',name:'Training Provider',purpose:'Learners & institutions',price:999,features:['Publish detailed courses and programmes','Match with learner requirements','Explore institutional partnerships','Use Talind chat and approved direct-contact workflows']}
];
function money(n){return '₹'+Number(n).toLocaleString('en-IN')}
function chooseAudience(a){billing.audience=a;plans()}
plans=function(){const audience=billing.audience||state.role;const choices=[['learner','Students & parents'],['teacher','Teachers & experts'],['institution','Schools & colleges'],['training','Training providers']];const plansFor=paidPlans.filter(p=>p.role===audience);$('#main').innerHTML=intro('TALIND MEMBERSHIP','Choose the opportunity you want.','Students and parents use Talind free. For teachers, job seeking is free; offering tuition, coaching, mentoring, workshops or other paid services requires a Teacher Services membership.','Membership')+`<div class="tabs">${choices.map(([k,v])=>`<button class="chip ${k===audience?'active':''}" onclick="chooseAudience('${k}')">${v}</button>`).join('')}</div><div class="cards pricing-cards">${audience==='learner'?`<article class="card plan recommended"><span class="eyebrow">LEARN & DISCOVER</span><h3>Your next possibility</h3><div class="plan-price">Free</div><ul><li>Find tuition, coaching and skills training</li><li>Explore schools and colleges</li><li>Compare and shortlist profiles</li><li>Post learning needs</li></ul></article>`:(audience==='teacher'?`<article class="card plan"><span class="eyebrow">FIND YOUR NEXT ROLE</span><h3>Teacher Job Seeker</h3><div class="plan-price">Free</div><ul><li>Create a professional profile for employment</li><li>Explore teaching and faculty jobs</li><li>Apply, shortlist and communicate about job opportunities</li><li>No Teacher Services membership required for job seeking</li></ul></article>`:'')+plansFor.map(p=>`<article class="card plan"><span class="eyebrow">${p.purpose}</span><h3>${p.name}</h3><div class="plan-price">${money(p.price)}<small> / month</small></div><ul>${p.features.map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn light" onclick="toast('Online membership activation is coming soon.')">Coming soon</button></article>`).join('')}</div><section class="panel"><h2>Payments</h2><p class="muted">Online payment is not yet enabled. No card, UPI or banking information is collected on this page.</p></section>`;side('plans')};
